104	/* --------------------------------------------------------- akt 3 pin/ram -- */
105	.reveal-stage {
106	  background: #05070c;
107	  /* crossfade progress 0..1 across the opening 35% of the pin, and a
108	     triangular bump (4t(1-t)) that peaks at its midpoint: a static
109	     screenshot and a live-rendered iframe never align pixel-perfectly, and a
110	     brief blur bridges that mismatch instead of showing two overlapping
111	     images (emil-design-eng: "use blur to mask imperfect transitions"). */
112	  --xfade: calc(min(var(--sc-p, 0), 0.35) / 0.35);
113	  --xfade-blur: calc(4 * var(--xfade) * (1 - var(--xfade)) * 6px);
