116	  position: absolute; inset: 0; z-index: 3; pointer-events: none;
117	  transform-origin: 50.3% 51.5%;
118	  transform: scale(calc(1 + var(--xfade) * 0.282));
119	  opacity: calc(1 - var(--xfade));
