124	.reveal-frame {
125	  position: absolute; inset: 0; width: 100%; height: 100%; border: 0; z-index: 2;
126	  opacity: var(--xfade);
127	  filter: blur(var(--xfade-blur));
128	}
129	
130	/* -------------------------------------------------------------- akt 4 exit -- */
131	.exit-stage { background: var(--sc-canvas); overflow: clip; }
132	.exit-sweep { position: absolute; inset: 0; background: var(--paper); z-index: 4; }
133	.exit-frame {
134	  position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;
135	  z-index: 2; transform-origin: 20% 34%;
136	  transform: scale(calc(1 - min(var(--sc-p, 0), 0.55) * 1.38));
137	}
