139	  position: absolute; z-index: 5; left: var(--sc-gutter); right: var(--sc-gutter);
140	  bottom: clamp(2.5rem, 12vh, 6rem); max-width: 20ch;
141	  font-weight: 600; color: var(--ink-on-white);
