145	
146	/* ---------------------------------------------------------- reservläge -- */
147	.rm-only { background: var(--sc-canvas); }
148	.rm-section { position: relative; min-height: 100vh; min-height: 100svh; overflow: clip; }
149	.rm-section--hero { display: flex; flex-direction: column; justify-content: flex-end; padding: clamp(1.5rem,5vw,3rem); }
150	.rm-section__bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 0; }
151	.rm-section__scrim { position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, rgba(6,10,18,0.85) 0%, rgba(6,10,18,0.35) 45%, transparent 70%); }
152	.rm-hero-copy { position: relative; z-index: 2; max-width: 40rem; }
153	.rm-section--window { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--sc-5); background: #05070c; }
154	.rm-window-stage { position: relative; width: min(92vw, 1200px); aspect-ratio: 3 / 2; overflow: clip; border-radius: 2px; }
155	.rm-window-stage__photo, .rm-window-mask__fill { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
156	.rm-window-mask { position: absolute; z-index: 2; overflow: hidden; }
157	.rm-window-mask__glass { position: absolute; inset: 0; mix-blend-mode: multiply; background: linear-gradient(180deg, rgba(255,224,170,0.22), rgba(20,14,8,0.3)); }
