159	.rm-frame { width: min(94vw, 1400px); aspect-ratio: 16 / 9; border: 1px solid color-mix(in oklab, var(--sc-ink) 16%, transparent); }
160	.rm-caption { font-family: var(--sc-font-text); font-size: var(--sc-t-sm); color: var(--sc-ink-soft); text-align: center; margin: 0; }
